    Object verified_runtime_policy(const QJsonValue& value,const QString& thread,const QJsonValue& turn) {
        if(CodexAgent::policyPatch().isEmpty())return {};
        if(!value.isObject())throw std::runtime_error("Dedicated Edi policy proof is unavailable");
        const auto proof=value.toObject();
        const std::array<QLatin1StringView,17> fields{QLatin1StringView{"schema"},QLatin1StringView{"flavour"},QLatin1StringView{"upstreamVersion"},QLatin1StringView{"upstreamCommit"},QLatin1StringView{"sourcePatchSha256"},QLatin1StringView{"threadId"},QLatin1StringView{"turnId"},QLatin1StringView{"isolation"},QLatin1StringView{"toolMode"},QLatin1StringView{"sandbox"},QLatin1StringView{"approvalPolicy"},QLatin1StringView{"modelNetwork"},QLatin1StringView{"requestedTools"},QLatin1StringView{"advertisedTools"},QLatin1StringView{"dispatchEqualsAdvertisement"},QLatin1StringView{"model"},QLatin1StringView{"reasoningEffort"}};
        if(proof.size()!=fields.size())throw std::runtime_error("Dedicated Edi policy proof is malformed");
        for(auto at=proof.constBegin();at!=proof.constEnd();++at)if(std::none_of(fields.begin(),fields.end(),[&](auto key){return at.key()==key;}))throw std::runtime_error("Dedicated Edi policy proof is malformed");
        if(proof.value("schema")!="edi.runtime-policy/1" || proof.value("flavour")!="edi-app-server/1" ||
            proof.value("upstreamVersion")!=QString::fromLatin1(EDI_CODEX_RUNTIME_VERSION) || proof.value("upstreamCommit")!="092d3acd6bec3e3a14bdc7e7a2810ab628ab759d" ||
            proof.value("sourcePatchSha256")!=CodexAgent::policyPatch() || proof.value("threadId")!=thread || proof.value("turnId")!=turn ||
            proof.value("isolation")!="isolated" || proof.value("toolMode")!="direct" || proof.value("sandbox")!="readOnly" ||
            proof.value("approvalPolicy")!="never" || proof.value("modelNetwork")!=QJsonValue(false) ||
            proof.value("dispatchEqualsAdvertisement")!=QJsonValue(true) || proof.value("model")!=generic_settings_model ||
            proof.value("reasoningEffort")!=generic_settings_effort || !proof.value("advertisedTools").isArray())
            throw std::runtime_error("Dedicated Edi effective policy mismatch");
        const auto requested=proof.value("requestedTools");
        if(!requested.isArray() || requested.toArray().size()!=generic_requested_tool_count || generic_requested_tools_digest.size()!=32)
            throw std::runtime_error("Dedicated Edi intended catalogue changed");
        // Hash the actual original request catalogue, not a newly rebuilt
        // schema tree. Its persistent 32-byte identity belongs to this State.
        // Old proof, current parsed record, encoded bytes and digest coexist.
        const auto requestedBytes=generic_size(requested,Limits::context_bytes);
        const auto encoded=QJsonDocument(requested.toArray()).toJson(QJsonDocument::Compact);
        if(static_cast<quint64>(encoded.size())!=requestedBytes || QCryptographicHash::hash(encoded,QCryptographicHash::Sha256)!=generic_requested_tools_digest)
            throw std::runtime_error("Dedicated Edi intended catalogue changed");
        // The dedicated host proves full parsed-schema equality with these
        // exact requested schemas. Independently reject extra/shadow namespaces
        // and missing/duplicate/nonfunction/deferred callable advertisements.
        static constexpr std::array<QStringView,22> expectedNames{u"inspect_project",u"list_parameters",u"diagnostics",u"set_parameters",u"set_free",u"run_fit",u"undo_fit",u"create_cwl_project",u"acquire_inputs",u"save_project",u"add_relations",u"edit_relation",u"edit_background",u"load_structure",u"create_experiment",u"set_experiment_type",u"load_data",u"read_selected_file",u"create_structure",u"edit_structure",u"edit_atom",u"edit_experiment"};
        std::array<bool,expectedNames.size()> names{};
        const auto accept=[&](const Object& function) {
            if(function.value("type")!="function" || !function.value("name").isString() ||
                function.value("defer_loading").toBool() || !function.value("parameters").isObject())
                throw std::runtime_error("Dedicated Edi advertisement is invalid");
            const auto name=function.value("name").toString();
            const auto at=std::find(expectedNames.begin(),expectedNames.end(),QStringView(name));
            if(at==expectedNames.end() || names[at-expectedNames.begin()])throw std::runtime_error("Dedicated Edi advertisement is invalid");
            names[at-expectedNames.begin()]=true;
        };
        for(const auto& item:proof.value("advertisedTools").toArray()) {
            if(!item.isObject())throw std::runtime_error("Dedicated Edi advertisement is invalid");
            const auto spec=item.toObject();
            if(spec.value("type")=="namespace") {
                if(spec.value("name")!="functions" || !spec.value("tools").isArray())throw std::runtime_error("Dedicated Edi namespace is invalid");
                for(const auto& function:spec.value("tools").toArray())if(function.isObject())accept(function.toObject());else throw std::runtime_error("Dedicated Edi function is invalid");
            } else accept(spec);
        }
        if(generic_requested_tool_count!=static_cast<qsizetype>(names.size()) || !std::all_of(names.begin(),names.end(),[](bool present){return present;}))throw std::runtime_error("Dedicated Edi advertisement is incomplete");
        generic_size(proof,Limits::context_bytes);
        return proof;
    }
    static void scope_bytes(QCryptographicHash& hash, const char* data, std::size_t size) {
        hash.addData(QByteArrayView(data, static_cast<qsizetype>(size)));
    }
    static void scope_integer(QCryptographicHash& hash, quint64 value) {
        scope_bytes(hash, reinterpret_cast<const char*>(&value), sizeof(value));
    }
    static void scope_text(QCryptographicHash& hash, const std::string& value) {
        scope_integer(hash, value.size()); scope_bytes(hash, value.data(), value.size());
    }
    QByteArray raw_input_identity(ProjectViewModel* target) {
        if (!target) return {};
        const auto* model = target->assistantProject();
        if (!model) throw std::runtime_error("The original project input owner is unavailable");
        const auto stamp = [](const auto& experiment) {
            RawInputStamp result;
            result.experiment = experiment.get(); result.name = experiment->name.written();
            result.calculation_only = experiment->calculation_only; result.present = bool(experiment->data);
            result.powder=experiment->experiment_type.effective_sample_form()==edi::SampleFormEnum::POWDER;
            result.reflections_present=bool(experiment->reflections);
            if(experiment->reflections) {
                const auto& data=*experiment->reflections;
                result.h=data.index_h.written();result.k=data.index_k.written();result.l=data.index_l.written();
                result.reflection_intensity=data.intensity_meas.written();result.reflection_sigma=data.intensity_meas_su.written();
                result.wavelength=data.wavelength.written();
            }
            if (experiment->data) {
                const auto& data = *experiment->data;
                result.data = data.written.value(); result.theta = data.two_theta.written(); result.tof = data.time_of_flight.written();
                result.intensity = data.intensity_meas.written(); result.sigma = data.intensity_meas_su.written();
            }
            return result;
        };
        bool unchanged = disclosure_raw && disclosure_raw->project == target && disclosure_raw->model == model &&
            disclosure_raw->membership == model->experiments.record() && disclosure_raw->generation == model->experiments.generation() &&
            disclosure_raw->stamps.size() == model->experiments.size();
        if (unchanged) for (std::size_t i = 0; i < model->experiments.size(); ++i) {
            if (!(disclosure_raw->stamps[i] == stamp(model->experiments[i]))) { unchanged = false; break; }
        }
        if (unchanged) return disclosure_raw->digest;
        // Admit all borrowed raw columns before hashing; never copy scientific
        // arrays or touch calculated getters. The host's existing input limit
        // bounds this owner-thread walk independently of the context summary.
        quint64 bytes = 0;
        const auto admit = [&](quint64 size) {
            if (size > edi::assistant::SelectedFileLimits::collection_bytes - bytes)
                throw std::length_error("Project raw inputs exceed the bounded disclosure scope");
            bytes += size;
        };
        const auto column = [&](const auto& values) {
            using Value=typename std::remove_cvref_t<decltype(values)>::value_type;
            if (values.size() > edi::assistant::SelectedFileLimits::collection_bytes / sizeof(Value))
                throw std::length_error("Project raw input column exceeds capacity");
            admit(values.size() * sizeof(Value));
        };
        for (const auto& experiment : model->experiments) {
            admit(experiment->name.value().size());
            if(experiment->reflections) {
                const auto& data=*experiment->reflections;
                column(data.index_h.get());column(data.index_k.get());column(data.index_l.get());
                column(data.intensity_meas.get());column(data.intensity_meas_su.get());column(data.wavelength.get());
            }
            if (!experiment->data) continue;
            const auto& data = *experiment->data;
            if (data.two_theta) column(*data.two_theta);
            if (data.time_of_flight) column(*data.time_of_flight);
            column(data.intensity_meas.get()); column(data.intensity_meas_su.get());
        }

        RawInputCache next;
        next.project = target; next.model = model; next.membership = model->experiments.record(); next.generation = model->experiments.generation();
        next.stamps.reserve(model->experiments.size());
        QCryptographicHash hash(QCryptographicHash::Sha256);
        scope_integer(hash, model->experiments.size());
        const auto values = [&](const auto& vector) {
            scope_integer(hash, vector.size());
            using Value=typename std::remove_cvref_t<decltype(vector)>::value_type;
            scope_bytes(hash, reinterpret_cast<const char*>(vector.data()), vector.size() * sizeof(Value));
        };
        for (const auto& experiment : model->experiments) {
            next.stamps.push_back(stamp(experiment));
            scope_text(hash, experiment->name.value());scope_integer(hash,experiment->calculation_only);
            scope_integer(hash,experiment->experiment_type.effective_sample_form()==edi::SampleFormEnum::POWDER);
            scope_integer(hash,bool(experiment->reflections));
            if(experiment->reflections) {
                const auto& data=*experiment->reflections;
                values(data.index_h.get());values(data.index_k.get());values(data.index_l.get());
                values(data.intensity_meas.get());values(data.intensity_meas_su.get());values(data.wavelength.get());
            }
            scope_integer(hash,bool(experiment->data));
            if (!experiment->data) continue;
            const auto& data = *experiment->data;
            scope_integer(hash, bool(data.two_theta)); if (data.two_theta) values(*data.two_theta);
            scope_integer(hash, bool(data.time_of_flight)); if (data.time_of_flight) values(*data.time_of_flight);
            values(data.intensity_meas.get()); values(data.intensity_meas_su.get());
        }
        next.digest = hash.result(); disclosure_raw = std::move(next);
        return disclosure_raw->digest;
    }
    QByteArray selected_input_identity(const QMap<QString, QByteArray>& files) const {
        if (files.size() > static_cast<qsizetype>(edi::assistant::SelectedFileLimits::files))
            throw std::length_error("Selected input identity exceeds capacity");
        QCryptographicHash hash(QCryptographicHash::Sha256);
        scope_integer(hash, files.size());
        for (auto it = files.constBegin(); it != files.constEnd(); ++it) {
            if (it.key().size() > static_cast<qsizetype>(Limits::id_bytes) || it.value().size() > 2 * QCryptographicHash::hashLength(QCryptographicHash::Sha256))
                throw std::length_error("Selected input identity exceeds capacity");
            scope_integer(hash, it.key().size()); scope_bytes(hash, reinterpret_cast<const char*>(it.key().utf16()), it.key().size() * sizeof(QChar));
            scope_integer(hash, it.value().size()); scope_bytes(hash, it.value().constData(), it.value().size());
        }
        return hash.result();
    }
    std::shared_ptr<DisclosureScope> prepare_disclosure_scope(ProjectViewModel* target, const Object& context,
                                                             const QMap<QString, QByteArray>& files) {
        if (context.contains("error"))
            throw std::runtime_error("The current disclosure scope is unavailable");
        if (disclosure_capabilities.isEmpty()) {
            QFile index(":/edi/assistant/skills/index.json");
            if (!index.open(QIODevice::ReadOnly) || index.size() < 0 || index.size() > static_cast<qint64>(Limits::context_bytes))
                throw std::runtime_error("The bundled capability scope is unavailable");
            auto bytes = index.read(Limits::context_bytes + 1);
            if (bytes.size() > static_cast<qsizetype>(Limits::context_bytes)) throw std::length_error("Capability scope exceeds capacity");
            QCryptographicHash hash(QCryptographicHash::Sha256); hash.addData(bytes);
            // The typed tool registry is immutable within this process. Its
            // actual names already belong to the admitted context envelope;
            // do not reconstruct schema arrays merely to fingerprint scope.
            if (!context.value("native_actions").isArray()) throw std::runtime_error("The native capability scope is unavailable");
            const auto tools = context.value("native_actions").toArray();
            const auto tool_bytes = generic_size(tools, Limits::context_bytes);
            hash.addData(QJsonDocument(tools).toJson(QJsonDocument::Compact)); disclosure_capabilities = hash.result();
        }
        const auto context_bytes = generic_measured_size(context);
        const auto inputs = raw_input_identity(target);
        const auto selected = selected_input_identity(files);
        // Projection keeps a subset of the complete context fields. Admit its
        // JSON value and compact encoding simultaneously, plus the proof shell
        // and returned selected-input digest, before constructing that subset.
        const auto& model = context; // Structures/datasets are top-level context members.
        QJsonArray datasets;
        for (const auto& value : model.value("datasets").toArray()) {
            const auto row = value.toObject();
            datasets.append(Object{{"id",row.value("id")},{"sample_form",row.value("sample_form")},{"beam_mode",row.value("beam_mode")},
                {"probe",row.value("probe")},{"calculation_only",row.value("calculation_only")}});
        }
        const Object identity{{"structures",model.value("structures")},{"datasets",datasets}};
        generic_measured_size(identity);
        auto result = std::make_shared<DisclosureScope>();
        result->project = target; result->has_project = target != nullptr; result->model = target ? target->assistantProject() : nullptr;
        if (!skill_inventory || context.value("skill_sources").toObject().value("sha256").toString() != QString::fromLatin1(skill_inventory->fingerprint.toHex()))
            throw std::runtime_error("The captured skill inventory changed");
        result->skills = skill_inventory; result->skill_configuration = skill_source_serial;
        result->account = usage_epoch;
        result->inputs = inputs; result->selected = selected; result->capabilities = disclosure_capabilities;
        result->metadata = QCryptographicHash::hash(QJsonDocument(identity).toJson(QJsonDocument::Compact), QCryptographicHash::Sha256);
        return result;
    }
    static bool same_disclosure(const std::shared_ptr<const DisclosureScope>& a, const std::shared_ptr<const DisclosureScope>& b) {
        return a && b && a->has_project == b->has_project && (!a->has_project || (a->project && b->project)) &&
            a->project == b->project && a->model == b->model && a->account == b->account &&
            a->inputs == b->inputs && a->selected == b->selected && a->capabilities == b->capabilities && a->metadata == b->metadata && a->skill_configuration == b->skill_configuration &&
            a->skills && b->skills && a->skills->fingerprint == b->skills->fingerprint;
    }
    std::shared_ptr<const DisclosureScope> current_disclosure(const Object* supplied = nullptr) {
        const auto original = file_projection();
        const auto inventory = source_inventory();
        if (!original.input_current()) throw std::runtime_error("The original disclosure owner changed");
        if (!controller) throw std::runtime_error("The current project disclosure is unavailable");
        const auto revision = controller->revision();
        const auto inputs = raw_input_identity(project);
        const auto selected = selected_input_identity(generic_input_hashes);
        if (!supplied && disclosure_cache && disclosure_cache->project == project && disclosure_cache->has_project == bool(project) &&
            (!project || disclosure_cache->model == project->assistantProject()) && disclosure_cache->account == usage_epoch &&
            disclosure_revision.project_id == revision.project_id && disclosure_revision.revision == revision.revision &&
            disclosure_cache->inputs == inputs && disclosure_cache->selected == selected &&
            disclosure_cache->skill_configuration == skill_source_serial && disclosure_cache->skills &&
            disclosure_cache->skills->fingerprint == inventory->fingerprint) return disclosure_cache;
        const auto context = supplied ? *supplied : outgoing_context(inventory);
        if (!original.input_current()) throw std::runtime_error("The original disclosure owner changed");
        auto prepared = prepare_disclosure_scope(project, context, generic_input_hashes);
        disclosure_revision = revision; disclosure_cache = std::move(prepared);
        return disclosure_cache;
    }
    bool disclosure_approved() {
        const auto original = file_projection();
        const auto approved = approved_scope;
        if (!approved) return false;
        const auto actual = current_disclosure();
        return original.input_current() && approved_scope == approved && same_disclosure(approved, actual);
    }
    void append_native_context(Object& context,ProjectViewModel* target) {
        const auto publication=file_projection();
        const QPointer<ProjectViewModel> original(target);
        const auto* model=target?target->assistantProject():nullptr;
        if(target && !model)throw std::runtime_error("The original calculation model is unavailable");
        const auto membership=model?model->experiments.record():nullptr;
        const auto epoch=model?model->experiments.generation():0;
        const auto structure_membership=model?model->structures.record():nullptr;
        const auto structure_epoch=model?model->structures.generation():0;
        const QPointer<StructureViewModel> current_structure(target?target->currentStructure():nullptr);
        const QPointer<ExperimentViewModel> current_experiment(target?target->currentExperiment():nullptr);
        const auto* structure_owner=current_structure.data();const auto* experiment_owner=current_experiment.data();
        const auto current=[&] {
            return publication.input_current() && original==target && (!target ||
                (target->assistantProject()==model && model->experiments.record()==membership && model->experiments.generation()==epoch &&
                 model->structures.record()==structure_membership && model->structures.generation()==structure_epoch &&
                 (!structure_owner || current_structure) && (!experiment_owner || current_experiment) &&
                 target->currentStructure()==structure_owner && target->currentExperiment()==experiment_owner));
        };
        QJsonArray actions;
        for (const auto& name : assistant_native_tool_names()) actions.append(name);
        context["native_actions"] = actions;

        QJsonArray interface_groups;
        QString selected_structure_id,selected_experiment_id;
        // Read the same original model/order/tiers as CategoryGroup's Repeater.
        // Core parameter/file order is intentionally different from the sidebar.
        const auto append_groups=[&](CategoryListModel* rows,const std::string& name,bool structure) {
            const QPointer<CategoryListModel> categories(rows);
            const int count=rows?rows->rowCount():0;
            const auto owned=[&] {
                return current() && categories && categories->rowCount()==count &&
                    (structure?(current_structure && current_structure->categories()==categories):
                               (current_experiment && current_experiment->categories()==categories));
            };
            if(!owned())throw std::runtime_error("The original interface category owner changed");
            const auto native_bytes=std::max<quint64>(name.size(),sizeof("experiment")-1);
            if(native_bytes>Limits::id_bytes)throw std::length_error("Interface member identity exceeds capacity");
            if(!edi::assistant::detail::utf8(name))throw std::runtime_error("Interface member identity is not valid UTF-8");
            // Canonical native copy and decoded Qt member ID precede JSON growth.
            const auto minimum=sizeof(QArrayData)+alignof(std::max_align_t)+sizeof(QChar);
            if(!owned())throw std::runtime_error("The original interface category owner changed");
            // The selected-ID child outlives this temporary spelling and owns
            // its decoded/encoded role beside the original interface rows.

            const auto member=QString::fromStdString(structure?edi::KeyTraits<edi::Structure>::canonical(name):
                edi::KeyTraits<edi::BraggPdExperiment>::canonical(name));
            if(structure)selected_structure_id=member;else selected_experiment_id=member;
            const auto page=structure?QStringLiteral("structure"):QStringLiteral("experiment");
            for(const auto& tier:{QStringLiteral("Basic"),QStringLiteral("Extras")})for(int row=0;row<count;++row) {
                if(!owned())throw std::runtime_error("The original interface category owner changed");
                const auto index=categories->index(row,0);
                const auto category=categories->data(index,CategoryListModel::CategoryIdRole);
                const auto original_tier=categories->data(index,CategoryListModel::TierRole);
                const auto extras=categories->data(index,CategoryListModel::ExtrasPartRole);
                const auto admitted=categories->data(index,CategoryListModel::AdmittedRole);
                if(category.metaType().id()!=QMetaType::QString || original_tier.metaType().id()!=QMetaType::QString ||
                    extras.metaType().id()!=QMetaType::Bool || admitted.metaType().id()!=QMetaType::Bool)
                    throw std::runtime_error("The original interface category roles are unavailable");
                const auto category_id=category.toString();const auto category_tier=original_tier.toString(); // Borrow implicit-shared model text.
                if(category_id.isEmpty() || (category_tier!=QStringLiteral("Basic") && category_tier!=QStringLiteral("Extras")))
                    throw std::runtime_error("The original interface category roles are invalid");
                if(category_tier!=tier && !(tier==QStringLiteral("Extras") && extras.toBool()))continue;
                quint64 text_units=0,wire=sizeof("{\"page\":,\"member_id\":,\"category_id\":,\"tier\":,\"admitted\":false}")-1;
                for(const auto text:{QStringView(page),QStringView(member),QStringView(category_id),QStringView(tier)}) {
                    const auto bytes=skill_json_string_bytes(text);
                    if(bytes>Limits::context_bytes-wire)throw std::length_error("Interface category row exceeds capacity");
                    wire+=bytes;text_units+=text.size();
                }
                constexpr auto keys=sizeof("pagemember_idcategory_idtieradmitted")*sizeof(QChar);
                const auto owned_row=sizeof(Object)+10*sizeof(QJsonValue)+keys+4*minimum+2*(text_units+4)*sizeof(QChar);
                // New row/input and both old/replacement growing array owners
                // coexist until append returns. Retain their joint role with context.
                const auto role=2*(owned_row+wire+sizeof(QJsonValue));

                if(!owned())throw std::runtime_error("The original interface category owner changed");
                interface_groups.append(Object{{"page",page},{"member_id",member},{"category_id",category_id},
                    {"tier",tier},{"admitted",admitted.toBool()}});
            }
            if(!owned())throw std::runtime_error("The original interface category owner changed");
        };
        if(current_structure) {
            if(!current() || !target->structureModels().contains(current_structure))throw std::runtime_error("The original structure interface owner changed");
            const auto* member=current_structure->structure();
            if(std::none_of(model->structures.begin(),model->structures.end(),[&](const auto& held){return held.get()==member;}))
                throw std::runtime_error("The original structure interface member changed");
            append_groups(current_structure->categories(),member->name.value(),true);
        }
        if(current_experiment) {
            if(!current() || !target->experimentModels().contains(current_experiment))throw std::runtime_error("The original experiment interface owner changed");
            const auto* member=current_experiment->experiment();
            if(std::none_of(model->experiments.begin(),model->experiments.end(),[&](const auto& held){return held.get()==member;}))
                throw std::runtime_error("The original experiment interface member changed");
            append_groups(current_experiment->categories(),member->name.value(),false);
        }
        if(!current())throw std::runtime_error("The original interface read owner changed");
        QJsonArray calculations;
        if(model)for(const auto& held:model->experiments) {
            if(!current())throw std::runtime_error("The original calculation read owner changed");
            ExperimentViewModel* view=nullptr;
            for(auto* candidate:target->experimentModels())if(candidate && candidate->experiment()==held.get()) {
                if(view)throw std::runtime_error("The original calculation view is ambiguous");
                view=candidate;
            }
            const auto* pattern=view?view->pattern():nullptr;
            const auto error=pattern?pattern->calculationError():QString{}; // Implicit shared copy of existing published text.
            const auto units=std::min<quint64>(static_cast<quint64>(error.size()),Limits::error_bytes);
            const auto error_bytes=std::min<quint64>(3*units,Limits::error_bytes);
            if(!current())throw std::runtime_error("The original calculation read owner changed");
            Object row{{"dataset_id",QString::fromStdString(edi::KeyTraits<edi::BraggPdExperiment>::canonical(held->name.value()))},
                {"pattern_available",bool(pattern)}};
            if(pattern) {
                const auto text=bounded_error(error);
                const auto points=pattern->calculatedPointCount();
                if(points>(quint64(1)<<std::numeric_limits<double>::digits))
                    throw std::length_error("Calculation point count is not exactly representable");
                row["stale"]=pattern->stale();row["calculated_points"]=static_cast<double>(points);
                row["calculated_available"]=points>0;row["calculation_error_present"]=!error.isEmpty();
                row["calculation_error"]=text;row["calculation_error_complete"]=text==error;
            }
            calculations.append(std::move(row));
        }
        if(!current())throw std::runtime_error("The original calculation read owner changed");
        Object native_state{{"calculating",target && target->calculating()},
            {"fitting",target && target->fit()->nativeRunning()},{"fit_undo_available",target && target->fitUndoAvailable()},{"show_actions",show_actions},{"calculations",calculations},{"interface_groups",interface_groups}};
        if(!selected_structure_id.isEmpty())native_state["selected_structure_id"]=selected_structure_id;
        if(!selected_experiment_id.isEmpty())native_state["selected_experiment_id"]=selected_experiment_id;
        context["native_state"]=native_state;
        generic_measured_size(context);
    }
